  .rWdRxW_statusDot { animation: 2s ease 0s infinite normal none running rWdRxW_statusFlash; }
}

@media (prefers-reduced-motion: no-preference) {
  .rWdRxW_statusDot::after { animation: 2s ease 0s infinite normal none running rWdRxW_statusPulse; }
}

@media (prefers-reduced-motion: reduce) {
  .sx-1aquc0h.sx-1aquc0h { animation-name: none; }
  .sx-xl291s.sx-xl291s { transform: translate(-1.979%, 1.375%); }
  .sx-12w9bfk.sx-12w9bfk { transition-duration: 0s; }
