  .rgSKaG_fadeIn { animation: rgSKaG_fadeIn 1s ease var(--fade-delay,0s) backwards; }
}

@media (prefers-reduced-motion: no-preference) {
  ._X0uBq_animation[data-closed] { animation: _X0uBq_slideUp .18s var(--ease-out-quad) forwards; }
  ._X0uBq_animation[data-open] { animation: _X0uBq_slideDown .18s var(--ease-out-quad) forwards; }
